package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clk := newFakeClock()
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 10, 1, nil, true},
		{"zero capacity", 0, 1, clk, true},
		{"negative capacity", -1, 1, clk, true},
		{"zero rate", 10, 0, clk, true},
		{"negative rate", 10, -1, clk, true},
		{"valid", 10, 2, clk, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			b, err := New(tt.capacity, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tt.wantErr)
			}
			if !tt.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	tests := []struct {
		name   string
		advance time.Duration
		n      int
		want   bool
	}{
		{"consume one", 0, 1, true},
		{"consume all", 0, 5, true},
		{"insufficient", 0, 6, false},
		{"refill after advance", 500 * time.Millisecond, 1, true},
		{"zero tokens", 0, 0, true},
		{"negative tokens", 0, -1, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			clk := newFakeClock()
			b, err := New(5, 2, clk) // 2 tokens/sec
			if err != nil {
				t.Fatal(err)
			}
			if tt.advance > 0 {
				clk.Advance(tt.advance)
			}
			if got := b.AllowN(tt.n); got != tt.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tt.n, got, tt.want)
			}
		})
	}
}

func TestRefillCapsAtCapacity(t *testing.T) {
	clk := newFakeClock()
	b, err := New(3, 10, clk)
	if err != nil {
		t.Fatal(err)
	}
	if !b.AllowN(3) {
		t.Fatal("expected initial tokens")
	}
	clk.Advance(time.Hour)
	if got := b.Tokens(); got != 3 {
		t.Fatalf("Tokens() = %v, want 3", got)
	}
}

func TestConcurrentAllow(t *testing.T) {
	clk := newFakeClock()
	b, err := New(100, 1000, clk)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	allowed := make(chan bool, 200)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			allowed <- b.Allow()
		}()
	}
	wg.Wait()
	close(allowed)
	count := 0
	for ok := range allowed {
		if ok {
			count++
		}
	}
	if count != 100 {
		t.Fatalf("allowed = %d, want 100", count)
	}
}
