package ratelimit

import (
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func (f *fakeClock) Now() time.Time {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.t
}

func (f *fakeClock) Advance(d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.t = f.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	fc := &fakeClock{t: time.Unix(0, 0)}
	cases := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 1, 1, nil, true},
		{"zero capacity", 0, 1, fc, true},
		{"negative capacity", -1, 1, fc, true},
		{"zero rate", 1, 0, fc, true},
		{"negative rate", 1, -1, fc, true},
		{"valid", 5, 2, fc, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			b, err := New(tc.capacity, tc.rate, tc.clock)
			if tc.wantErr && err == nil {
				t.Fatal("expected error")
			}
			if !tc.wantErr && err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if !tc.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	cases := []struct {
		name    string
		cap     int
		rate    float64
		advance time.Duration
		n       int
		want    bool
	}{
		{"full bucket allows burst", 5, 1, 0, 5, true},
		{"exceeds capacity", 5, 1, 0, 6, false},
		{"zero n", 2, 1, 0, 0, true},
		{"refills over time", 2, 2, time.Second, 2, true},
		{"partial refill insufficient", 2, 1, 1500 * time.Millisecond, 2, false},
		{"partial refill sufficient", 2, 1, 1500 * time.Millisecond, 1, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			fc := &fakeClock{t: time.Unix(0, 0)}
			b, err := New(tc.cap, tc.rate, fc)
			if err != nil {
				t.Fatal(err)
			}
			fc.Advance(tc.advance)
			if got := b.AllowN(tc.n); got != tc.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tc.n, got, tc.want)
			}
		})
	}
}

func TestConcurrentAllowN(t *testing.T) {
	fc := &fakeClock{t: time.Unix(0, 0)}
	b, err := New(100, 1, fc)
	if err != nil {
		t.Fatal(err)
	}
	var allowed atomic.Int32
	var wg sync.WaitGroup
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.Allow() {
				allowed.Add(1)
			}
		}()
	}
	wg.Wait()
	if got := allowed.Load(); got != 100 {
		t.Fatalf("allowed = %d, want 100", got)
	}
}
